package com.securelib.crypto

import java.security.{MessageDigest, SecureRandom}
import java.util.{Base64, concurrent}
import javax.crypto.{Cipher, SecretKeyFactory}
import javax.crypto.spec.{IvParameterSpec, PBEKeySpec, SecretKeySpec}
import scala.collection.concurrent.TrieMap
import scala.util.{Try, Success, Failure}

object CryptoRedirectService {

  private val rateLimitMap = TrieMap[String, RateLimitEntry]()
  private val nonceStore = TrieMap[String, Long]()
  private val MAX_REQUESTS_PER_WINDOW = 100
  private val WINDOW_MS = 60000L
  private val MAX_RETRIES = 3
  // Require the HMAC secret to be supplied via environment; never fall back to a
  // hard-coded/default key. Fail fast if it is missing or too weak.
  private val HMAC_KEY: String = {
    val key = sys.env.getOrElse(
      "HMAC_SECRET",
      throw new IllegalStateException(
        "HMAC_SECRET environment variable must be set to a strong secret"
      )
    )
    if (key.length < 32) {
      throw new IllegalStateException(
        "HMAC_SECRET must be at least 32 characters long"
      )
    }
    key
  }

  case class RateLimitEntry(count: Int, windowStart: Long)

  case class RedirectToken(
    targetUrl: String,
    nonce: String,
    timestamp: Long,
    signature: String
  )

  private val ALLOWED_DOMAINS = Set(
    "app.example.com",
    "auth.example.com",
    "cdn.example.com",
    "api.example.com"
  )

  def computeHmac(data: String): String = {
    val mac = javax.crypto.Mac.getInstance("HmacSHA256")
    val keySpec = new SecretKeySpec(HMAC_KEY.getBytes("UTF-8"), "HmacSHA256")
    mac.init(keySpec)
    Base64.getUrlEncoder.withoutPadding.encodeToString(mac.doFinal(data.getBytes("UTF-8")))
  }

  def generateNonce(): String = {
    val bytes = new Array[Byte](16)
    new SecureRandom().nextBytes(bytes)
    Base64.getUrlEncoder.withoutPadding.encodeToString(bytes)
  }

  def createRedirectToken(url: String): Either[String, RedirectToken] = {
    if (!isDomainAllowed(url)) {
      return Left("Domain not in allowlist")
    }
    val nonce = generateNonce()
    val timestamp = System.currentTimeMillis()
    val payload = s"$url|$nonce|$timestamp"
    val signature = computeHmac(payload)
    nonceStore.put(nonce, timestamp)
    Right(RedirectToken(url, nonce, timestamp, signature))
  }

  def checkRateLimit(clientId: String): Boolean = {
    val now = System.currentTimeMillis()
    rateLimitMap.get(clientId) match {
      case Some(entry) if (now - entry.windowStart) < WINDOW_MS =>
        if (entry.count >= MAX_REQUESTS_PER_WINDOW) false
        else {
          rateLimitMap.update(clientId, entry.copy(count = entry.count + 1))
          true
        }
      case _ =>
        rateLimitMap.put(clientId, RateLimitEntry(1, now))
        true
    }
  }

  def extractDomain(url: String): String = {
    Try {
      val uri = new java.net.URI(url)
      Option(uri.getHost).map(_.toLowerCase).getOrElse("")
    }.getOrElse("")
  }

  def isDomainAllowed(url: String): Boolean = {
    val domain = extractDomain(url)
    if (domain.isEmpty) return false
    // Strict exact match only - no subdomain matching
    ALLOWED_DOMAINS.contains(domain)
  }

  def validateTokenIntegrity(token: RedirectToken): Boolean = {
    val payload = s"${token.targetUrl}|${token.nonce}|${token.timestamp}"
    val expectedSig = computeHmac(payload)
    // Constant-time comparison to prevent timing attacks
    MessageDigest.isEqual(expectedSig.getBytes, token.signature.getBytes)
  }

  def validateNonce(nonce: String): Boolean = {
    nonceStore.remove(nonce) match {
      case Some(ts) =>
        val age = System.currentTimeMillis() - ts
        age < 300000L // 5 minute expiry
      case None => false
    }
  }

  def resolveRedirect(token: RedirectToken, clientId: String, attempt: Int = 0): Either[String, String] = {
    if (!checkRateLimit(clientId)) {
      return Left("Rate limit exceeded")
    }

    if (!validateTokenIntegrity(token)) {
      if (attempt < MAX_RETRIES) {
        Thread.sleep(Math.pow(2, attempt).toLong * 100)
        return resolveRedirect(token, clientId, attempt + 1)
      }
      return Left("Token integrity check failed")
    }

    if (!validateNonce(token.nonce)) {
      return Left("Invalid or expired nonce")
    }

    val tokenAge = System.currentTimeMillis() - token.timestamp
    if (tokenAge > 300000L) {
      return Left("Token expired")
    }

    // Domain validation on the raw URL from the token
    if (!isDomainAllowed(token.targetUrl)) {
      return Left("Domain not in allowlist")
    }

    Right(token.targetUrl)
  }

  def processRedirectRequest(encodedToken: String, clientId: String): Either[String, String] = {
    Try {
      val parts = new String(Base64.getUrlDecoder.decode(encodedToken), "UTF-8").split("\\|")
      if (parts.length != 4) throw new IllegalArgumentException("Invalid token format")
      RedirectToken(parts(0), parts(1), parts(2).toLong, parts(3))
    } match {
      case Success(token) => resolveRedirect(token, clientId)
      case Failure(e) => Left(s"Token parse error: ${e.getMessage}")
    }
  }
}
